hints.pseudocode:
for right in 0 .. n - 1:
  while maxDeque not empty and numbers[maxDeque.back] <= numbers[right]: pop back; push right on maxDeque
  while minDeque not empty and numbers[minDeque.back] >= numbers[right]: pop back; push right on minDeque
  while numbers[maxDeque.front] - numbers[minDeque.front] > limit:
    left += 1; drop the front of a deque if its index is now < left
  best = max(best, right - left + 1)
